from html import escape

def render(comparison):
    e=lambda v:escape(str(v),quote=True)
    rows=[];timelines=[]
    for r in comparison['comparisons']:
        rows.append('<tr>'+''.join('<td>'+e(v)+'</td>' for v in (r['route'],'FEASIBLE' if r['admissible'] else 'REFUSED',', '.join(x['code'] for x in r['failures']) or 'None',r['cost']['partial_operating_usd'],r['energy']['proposed_event_kwh'],max((j['completion_s'] or 0 for j in r['jobs']),default=0)))+'</tr>')
        lines=[]
        for event in sorted(r['proposal']['events'],key=lambda x:(x['start_s'],x['id'])):
            lines.append('<tr>'+''.join('<td>'+e(v)+'</td>' for v in (event['node'],event['kind'],event['start_s'],event['end_s'],event['power_kw'],event['heat_w']))+'</tr>')
        lifecycle=r['diligence']['lifecycle']
        lifecycle_text='Unknown: no lifecycle sensitivity supplied' if lifecycle is None else 'Separate '+e(r['diligence']['lifecycle_horizon_years'])+' year sensitivity: '+e(lifecycle['result']['totals']['cost_per_discounted_useful_kw_year'])+' USD per discounted useful kW-year; not a mission total'
        qualities=', '.join(e(j['id'])+': '+e(j['quality'])+' / minimum '+e(j['required_quality']) for j in r['jobs'])
        timelines.append('<section><h2>'+e(r['route'])+' timeline</h2><p>'+lifecycle_text+'</p><p>Declared quality: '+qualities+'</p><div class="scroll"><table><tr>'+''.join('<th scope="col">'+x+'</th>' for x in ('Node','Event','Start(s)','End(s)','Power(kW)','Heat(W)'))+'</tr>'+''.join(lines)+'</table></div><p>Receipt <code>'+e(r['receipt_id'])+'</code></p></section>')
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Capacity Orbital mission workspace</title><style>body{font:16px/1.5 system-ui;background:#f1f5fa;color:#142b43;margin:0}main{max-width:1200px;margin:auto;padding:24px}section{background:white;border:1px solid #afc1d3;border-radius:10px;padding:20px;margin:20px 0}table{border-collapse:collapse;min-width:700px}td,th{padding:10px;border-bottom:1px solid #ccd8e4;text-align:left}.scroll{overflow:auto}code{overflow-wrap:anywhere}@media(max-width:600px){main{padding:12px}}</style><main><h1>Capacity Orbital mission workspace</h1><p>One synthetic mission · three coupled policies · no flight execution</p><section><h2>Useful completion and limiting resources</h2><div class="scroll"><table><tr>'''+''.join('<th scope="col">'+x+'</th>' for x in ('Policy','Outcome','Limiting reason','Partial cost(USD)','Proposed event energy(kWh)','Latest predicted completion(s)'))+'</tr>'+''.join(rows)+'''</table></div><p>All policies preserve jobs, deadlines, quality floors and prices. A packet arrival is not useful completion until required processing finishes. Failed mission proposals are not executed or billed. Ground quality is a supplied synthetic assumption, not measured perfect accuracy.</p><p>Partial operating cost includes declared compute time and network transfer prices only. Lifecycle totals remain separate; no launch, hardware or amortized mission total is silently inferred.</p></section>'''+''.join(timelines)+'''<section><h2>Capabilities and acceptance</h2><p>One orbital origin, one ground compute lane, optional relay nodes. Compute, network and declared battery/linear thermal profiles share one timeline. Heat is explicitly supplied, not automatically derived from electrical losses. Real telemetry, orbital geometry, Tool Guard enforcement, hardware qualification, production metering and signing are not implemented here. All evidence is synthetic predicted consistency, not authenticity.</p><p>Peer review and designated acceptance remain open. Browser visual qualification is separate. No automatic policy promotion or baseline change.</p><p>Mission input <code>'''+e(comparison['input_sha256'])+'</code></p><p>Source <code>'+e(comparison['source_sha256'])+'</code></p></section></main></html>'
